{
    if (!$this->isInfiniteDate($date) && !($date = ([$this->dateClass, 'make'])($date))) {
        throw new InvalidPeriodDateException('Invalid start date.');
    }

    $self = $this->copyIfImmutable();
    $self->startDate = $date;

    if ($inclusive !== null) {
